from svg import box, t, arrow, line, svg

FIG = svg(1180, 430, 'The fair-twist test: three rules, and how three classic con films pass them',
          t(590, 32, 'THE FAIR-TWIST TEST', 's-t') +
          box(20, 56, 360, 120, 's-box-a') + t(200, 96, '1. SEED THE FACT', 's-t-b') + t(200, 130, 'it is on screen, in plain sight', 's-t-sm') +
          box(410, 56, 360, 120, 's-box-a') + t(590, 96, '2. HIDE THE MEANING', 's-t-b') + t(590, 130, 'give the audience a wrong frame', 's-t-sm') +
          box(800, 56, 360, 120, 's-box-a') + t(980, 96, '3. CHARGE A PRICE', 's-t-b') + t(980, 130, 'the reveal costs a relationship', 's-t-sm') +
          arrow(380, 116, 408, 116) + arrow(770, 116, 798, 116) +
          box(20, 206, 1140, 60, 's-card', 10) + t(40, 244, 'NINE QUEENS (2000): the frame is "two grifters vs the world". The price: the partner was the mark.', 's-t-sm', 'start') +
          box(20, 280, 1140, 60, 's-card', 10) + t(40, 318, 'HOUSE OF GAMES (1987): the frame is "an expert studying con men". The price: her sense of who she is.', 's-t-sm', 'start') +
          box(20, 354, 1140, 60, 's-card', 10) + t(40, 392, 'THE GRIFTERS (1990): the frame is "mother and son reconciling". The price: the son.', 's-t-sm', 'start'))

